/// <summary>
/// Extension of class <c>SalesInvoiceDP</c>
/// </summary>
[ExtensionOf(classStr(SalesInvoiceDP))]
final class KPMGSalesInvoiceDP_Extension
{
    
}

Method.Source:
    /// <summary>
    /// Populates the Delivery address information into the <c>SalesInvoiceHeaderFooterTmp</c> table buffer.
    /// </summary>
    /// <param name="_common">
    /// The <c>SalesInvoiceHeaderFooterTmp</c> record stores has the invoice header information.
    /// </param>
    [DataEventHandlerAttribute(tableStr(SalesInvoiceHeaderFooterTmp), DataEventType::Inserting),
    SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface')]
    public static void TmpVendInvoiceDocumentInsertEvent(Common _common, DataEventArgs _e)
    {
        SalesInvoiceHeaderFooterTmp salesInvoiceHeaderFooterTmp = _common;
        SalesTable                  salesTable;
        MarkupTrans                 markupTrans;
        CustInvoiceJour             custInvoiceJour = CustInvoiceJour::findRecId(salesInvoiceHeaderFooterTmp.JournalRecId);

        salesTable = SalesTable::find(salesInvoiceHeaderFooterTmp.SalesId);
        salesInvoiceHeaderFooterTmp.KPMGDeliveryName        = salesTable.DeliveryName;
        salesInvoiceHeaderFooterTmp.KPMGDeliveryAddress     = salesTable.deliveryAddressing();
        salesInvoiceHeaderFooterTmp.KPMGDeliveryDate        = salesTable.DeliveryDate;
        salesInvoiceHeaderFooterTmp.KPMGOrderDiscount       = salesTable.DiscPercent;
        salesInvoiceHeaderFooterTmp.KPMGCashDiscDesc        = CashDisc::find(salesTable.CashDisc).Description;
        salesInvoiceHeaderFooterTmp.KPMGPurchOrderFormNum   = salesTable.PurchOrderFormNum;

        salesInvoiceHeaderFooterTmp.KPMGHeaderCharges       = "";
        salesInvoiceHeaderFooterTmp.KPMGHeaderChargesValue  = "";
        while select markupTrans
            where markupTrans.TransTableId   == custInvoiceJour.TableId
            && markupTrans.TransRecId        == custInvoiceJour.RecId
        {
            // Filter out ledger to Ledger.
            if (!(markupTrans.markuptable().CustType == MarkupType::LedgerAccount &&
                markupTrans.markuptable().VendType == MarkupType::LedgerAccount))
            {
                salesInvoiceHeaderFooterTmp.KPMGHeaderCharges       += markupTrans.MarkupCode + '\n';
                salesInvoiceHeaderFooterTmp.KPMGHeaderChargesValue  += strFmt('%1',markupTrans.CalculatedAmount) + '\n';
            }            
        }

    }

/// <summary>
/// Populates the invoice header information into the <c>SalesInvoiceHeaderFooterTmp</c> table buffer.
/// </summary>
/// <param name="_custInvoiceJour">
/// The <c>CustInvoiceJour</c> record that has the invoice header information.
/// </param>
/// <param name="_companyInfo">
/// The <c>CompanyInfo</c> record that has the company information.
/// </param>
/// <remarks>
/// This method will insert the invoice header information into the <c>SalesInvoiceHeaderFooterTmp</c>
/// table which is only used for Eastern European countries and other countries that need customization
/// from the SYS layer functionality.
/// </remarks>
protected void populateSalesInvoiceHeaderFooterTmp(CustInvoiceJour _custInvoiceJour, CompanyInfo _companyInfo)
{
    next populateSalesInvoiceHeaderFooterTmp(_custInvoiceJour, _companyInfo);
    salesInvoiceHeaderFooterTmp.CompanyEmail = _companyInfo.email();
}

    /// <summary>
    /// Populates the invoice detail information into the <c>SalesInvoiceTmp</c> table buffer.
    /// </summary>
    /// <param name="_custInvoiceJour">
    /// The <c>CustInvoiceJour</c> record that has the invoice header information.
    /// </param>
    /// <param name="_custInvoiceTrans">
    /// The <c>CustInvoiceTrans</c> record that has the invoice details information.
    /// </param>
    /// <param name="_taxSpec">
    /// The <c>TaxSpec</c> class instance that has the taxes information.
    /// </param>
    /// <param name="_custPaymSchedLine">
    /// The <c>CustPaymSchedLine</c> record that has the payment schedules information.
    /// </param>
    /// <param name="_prepaymentCustTrans">
    /// The <c>CustTrans</c> record that has the prepayment information.
    /// </param>
    /// <param name="_prepaymentTaxTrans">
    /// The <c>TaxTrans</c> record that has the prepayment taxes information.
    /// </param>
    protected void populateSalesInvoiceTmp(CustInvoiceJour _custInvoiceJour,
        CustInvoiceTrans _custInvoiceTrans,
        TaxSpec _taxSpec,
        CustPaymSchedLine _custPaymSchedLine,
        CustTrans _prepaymentCustTrans,
        TaxTrans _prepaymentTaxTrans)
    {
        next populateSalesInvoiceTmp(_custInvoiceJour, _custInvoiceTrans, _taxSpec
            , _custPaymSchedLine, _prepaymentCustTrans, _prepaymentTaxTrans);

        if (!salesInvoiceTmp.TaxAmount)
        {
            salesInvoiceTmp.TaxAmount = _custInvoiceTrans.TaxAmount;
        }

        QueryRun tradeLoopTrans = new tradeLoopTrans(_custInvoiceTrans, tableNum(markupTrans)).buildQueryRun();
        
        salesInvoiceTmp.MCRMarkupTxt = SysLabel::labelId2String(literalStr("@SYS308474"),  _custInvoiceJour.LanguageId);

        while (tradeLoopTrans.next())
        {
            MarkupTrans markupTransLocal = tradeLoopTrans.get(tableNum(markupTrans));

            // Filter out ledger to Ledger.
            if (!(markupTransLocal.markuptable().CustType == MarkupType::LedgerAccount &&
                markupTransLocal.markuptable().VendType == MarkupType::LedgerAccount))
            {
                salesInvoiceTmp.MCRMarkupTxt += '\n' + markupTransLocal.MarkupCode + " = " +strFmt('%1',markupTransLocal.CalculatedAmount) ;
                //_salesInvoice.MCRMarkupValue = 1;
                //markupAmt += markupTransLocal.CalculatedAmount;
            }
        }
    }
